CREATE TABLE "store_product" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(120) NOT NULL, "slug" varchar(140) NOT NULL UNIQUE, "description" text NOT NULL, "sku" varchar(40) NOT NULL, "price_cents" integer unsigned NOT NULL CHECK ("price_cents" >= 0), "currency" varchar(3) NOT NULL, "image_url" varchar(200) NOT NULL, "stock" integer unsigned NOT NULL CHECK ("stock" >= 0), "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "store_order" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "status" varchar(16) NOT NULL, "currency" varchar(3) NOT NULL, "total_cents" integer unsigned NOT NULL CHECK ("total_cents" >= 0), "stripe_checkout_session_id" varchar(255) NULL UNIQUE, "stripe_payment_intent_id" varchar(255) NOT NULL, "customer_email" varchar(254) NOT NULL, "shipping_name" varchar(120) NOT NULL, "shipping_line1" varchar(200) NOT NULL, "shipping_line2" varchar(200) NOT NULL, "shipping_city" varchar(120) NOT NULL, "shipping_state" varchar(120) NOT NULL, "shipping_postal_code" varchar(20) NOT NULL, "shipping_country" varchar(2) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "paid_at" datetime NULL, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "store_orderitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "product_name" varchar(120) NOT NULL, "unit_price_cents" integer unsigned NOT NULL CHECK ("unit_price_cents" >= 0), "quantity" integer unsigned NOT NULL CHECK ("quantity" >= 0), "order_id" bigint NOT NULL REFERENCES "store_order" ("id") DEFERRABLE INITIALLY DEFERRED, "product_id" bigint NOT NULL REFERENCES "store_product" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX "store_order_status_69bd39aa" ON "store_order" ("status");
CREATE INDEX "store_order_user_id_ae5f7a5f" ON "store_order" ("user_id");
CREATE INDEX "store_orderitem_order_id_acf8722d" ON "store_orderitem" ("order_id");
CREATE INDEX "store_orderitem_product_id_f2b098d4" ON "store_orderitem" ("product_id");
